def solve(grid):
    """Count islands in a binary grid (batch 2) with tolerant input.
    Cells that evaluate to true (1, True, "1", etc.) are considered land.
    Connectivity is 4-directional.
    """
    if not grid:
        return 0
    m = len(grid)
    # Determine column count safely (handle ragged rows)
    n = max((len(row) for row in grid), default=0)
    visited = [[False] * n for _ in range(m)]
    def is_land(val):
        # Determine if a cell represents land (1)
        if isinstance(val, bool):
            return val
        if isinstance(val, (int, float)):
            return int(val) == 1
        try:
            return int(val) == 1
        except Exception:
            return False
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < len(grid[nx]):
                    if not visited[nx][ny] and is_land(grid[nx][ny]):
                        stack.append((nx, ny))
    count = 0
    for i in range(m):
        for j in range(len(grid[i])):
            if not visited[i][j] and is_land(grid[i][j]):
                count += 1
                dfs(i, j)
    return count

