def solve(s):
    """Run‑length encode the input.
    Accepts strings, bytes, bytearray, or any iterable of hashable items.
    Returns a list of [element, count] pairs, where element is the original
    item (bytes are decoded to a string using utf‑8). An empty input yields []
    """
    # Handle None or falsy as empty
    if not s:
        return []
    # If it's bytes or bytearray, decode to string
    if isinstance(s, (bytes, bytearray)):
        try:
            s = s.decode()
        except Exception:
            # Fallback: treat as iterable of ints
            pass
    # Try to get an iterator
    try:
        iterator = iter(s)
    except TypeError:
        # Not iterable, cannot encode
        return []
    # Get first element
    try:
        prev = next(iterator)
    except StopIteration:
        return []
    count = 1
    result = []
    for cur in iterator:
        if cur == prev:
            count += 1
        else:
            result.append([prev, count])
            prev = cur
            count = 1
    result.append([prev, count])
    return result

